widget.starter:
double max_via_pointer(const double* begin, const double* end) {
    // walk a pointer from begin up to, not including, end
    return 0;
}

widget.solution:
double max_via_pointer(const double* begin, const double* end) {
    if (begin == end) return 0;
    double best = *begin;
    for (const double* p = begin + 1; p != end; ++p)
        if (*p > best) best = *p;
    return best;
}

